import re

def validate_corporate_password(password: str) -> bool:
    """Validate password against IT Security Policy POL-IT-004 requirements."""
    if len(password) < 12:
        return False
    if not re.search(r'[A-Z]', password):
        return False
    if not re.search(r'[a-z]', password):
        return False
    if not re.search(r'[0-9]', password):
        return False
    if not re.search(r'[!@#$%^&*]', password):
        return False
    return True

from typing import List, Dict

def compute_rrf_scores(dense_ranked_ids: List[str], bm25_ranked_ids: List[str], k: int = 60) -> Dict[str, float]:
    """Compute Reciprocal Rank Fusion (RRF) scores for hybrid retrieval."""
    rrf_scores: Dict[str, float] = {}
    for rank, doc_id in enumerate(dense_ranked_ids, start=1):
        rrf_scores[doc_id] = rrf_scores.get(doc_id, 0.0) + (1.0 / (k + rank))
    for rank, doc_id in enumerate(bm25_ranked_ids, start=1):
        rrf_scores[doc_id] = rrf_scores.get(doc_id, 0.0) + (1.0 / (k + rank))
    return dict(sorted(rrf_scores.items(), key=lambda item: item[1], reverse=True))

import chromadb
from typing import List, Dict, Any

def query_policy_collection(client: chromadb.Client, collection_name: str, query_embedding: List[float], department: str = 'HR') -> Dict[str, Any]:
    """Query ChromaDB collection with strict metadata filtering."""
    collection = client.get_collection(name=collection_name)
    results = collection.query(
        query_embeddings=[query_embedding],
        n_results=5,
        where={
            "department": {"$eq": department}
        }
    )
    return results

import math
from typing import List

def cosine_similarity(vec_a: List[float], vec_b: List[float]) -> float:
    """Compute cosine similarity between two embedding vectors."""
    if len(vec_a) != len(vec_b) or not vec_a:
        return 0.0
    dot_product = sum(a * b for a, b in zip(vec_a, vec_b))
    norm_a = math.sqrt(sum(a * a for a in vec_a))
    norm_b = math.sqrt(sum(b * b for b in vec_b))
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return dot_product / (norm_a * norm_b)
